class Solution:
    def dieSimulator(self, n: int, rollMax: list[int]) -> int:
        MOD = 10**9 + 7
        # dp[face][consecutive_count]
        dp = [[0] * 16 for _ in range(6)]
        for f in range(6):
            dp[f][1] = 1

        for _ in range(n - 1):
            nxt = [[0] * 16 for _ in range(6)]
            face_sums = [sum(dp[f]) % MOD for f in range(6)]
            total_sum = sum(face_sums) % MOD

            for f in range(6):
                # Different face
                nxt[f][1] = (total_sum - face_sums[f]) % MOD
                # Same face
                for k in range(2, rollMax[f] + 1):
                    nxt[f][k] = dp[f][k - 1] % MOD
            dp = nxt

        return sum(sum(dp[f]) for f in range(6)) % MOD

class Solution {
public:
    int dieSimulator(int n, std::vector<int>& rollMax) {
        long long MOD = 1e9 + 7;
        std::vector<std::vector<long long>> dp(6, std::vector<long long>(16, 0));
        for (int f = 0; f < 6; ++f) dp[f][1] = 1;

        for (int step = 1; step < n; ++step) {
            std::vector<std::vector<long long>> nxt(6, std::vector<long long>(16, 0));
            std::vector<long long> faceSums(6, 0);
            long long totalSum = 0;
            for (int f = 0; f < 6; ++f) {
                for (int k = 1; k <= 15; ++k) faceSums[f] = (faceSums[f] + dp[f][k]) % MOD;
                totalSum = (totalSum + faceSums[f]) % MOD;
            }
            for (int f = 0; f < 6; ++f) {
                nxt[f][1] = (totalSum - faceSums[f] + MOD) % MOD;
                for (int k = 2; k <= rollMax[f]; ++k) {
                    nxt[f][k] = dp[f][k - 1] % MOD;
                }
            }
            dp = std::move(nxt);
        }
        long long ans = 0;
        for (int f = 0; f < 6; ++f) {
            for (int k = 1; k <= 15; ++k) ans = (ans + dp[f][k]) % MOD;
        }
        return ans;
    }
};

